import{_ as a,c as l,o as s,a3 as e}from"./chunks/framework.CoV49S2T.js";const k=JSON.parse('{"title":"故障排除","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1787301752000}'),t={name:"zh-CN/guide/troubleshooting.md"};function o(n,i,r,h,p,d){return s(),l("div",null,[...i[0]||(i[0]=[e(`<h1 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h1><p>本页汇总了 ClipboxAI 在 macOS 上的常见问题及解决方法。</p><h2 id="应用无法启动或启动时崩溃" tabindex="-1">应用无法启动或启动时崩溃 <a class="header-anchor" href="#应用无法启动或启动时崩溃" aria-label="Permalink to &quot;应用无法启动或启动时崩溃&quot;">​</a></h2><ol><li>确保你的 macOS 版本满足最低要求（macOS 14 Sonoma 及以上）。</li><li>退出并重新启动应用。</li><li>重启你的 Mac。</li><li><s>如果是从 GitHub Releases 下载的，请尝试最新版本或已公证的版本。</s></li><li>如果问题依旧，请收集日志（见下方）并提交 issue。</li></ol><h2 id="剪贴板历史未捕获复制内容" tabindex="-1">剪贴板历史未捕获复制内容 <a class="header-anchor" href="#剪贴板历史未捕获复制内容" aria-label="Permalink to &quot;剪贴板历史未捕获复制内容&quot;">​</a></h2><p>症状：新复制的内容未出现在历史面板中。</p><p>检查清单：</p><ol><li>确保应用正在运行，且菜单栏图标可见。</li><li>在 <strong>设置 → 隐私 / 通用（Settings → Privacy / General）</strong> 中确认已启用 <strong>剪贴板监控（Clipboard monitoring）</strong>。</li><li>应用需要相应的 macOS 权限才能在后台读取粘贴板——见<a href="/zh-CN/guide/permissions.html">权限说明</a>。</li><li>部分应用（密码管理器、安全输入字段）会主动阻止剪贴板访问；这属于预期行为。</li></ol><h2 id="云端-ai-操作没有返回结果" tabindex="-1">云端 AI 操作没有返回结果 <a class="header-anchor" href="#云端-ai-操作没有返回结果" aria-label="Permalink to &quot;云端 AI 操作没有返回结果&quot;">​</a></h2><p>症状：某项 AI 操作失败、卡住或显示配置错误。</p><p>检查清单：</p><ol><li>打开 <strong>设置 → AI（Settings → AI）</strong>，确认已选择提供商并填写了 key。</li><li>确认该 key 对该提供商有效，且具有配额 / 额度。</li><li>检查你的网络连接——云端 AI 需要访问互联网。</li><li>确认所选模型名称对提供商而言正确无误。</li><li>如果 AI 工具窗口中仍出现配置横幅，说明 key 未保存到 Keychain；请重新输入。</li></ol><h2 id="操作市场安装未添加操作" tabindex="-1">操作市场安装未添加操作 <a class="header-anchor" href="#操作市场安装未添加操作" aria-label="Permalink to &quot;操作市场安装未添加操作&quot;">​</a></h2><p>症状：点击 <strong>安装（Install）</strong> 后毫无反应，或应用未打开。</p><p>检查清单：</p><ol><li>深链接 <code>clipboxai://install?action=&lt;id&gt;</code> 必须由已安装的应用处理——请确保 ClipboxAI 已安装并正在运行。</li><li>如果你的浏览器拦截了该深链接，请复制它并手动打开，或从应用内的 <strong>Marketplace</strong> 标签页安装。</li><li>检查该操作 ID 是否仍在市场中发布。</li></ol><h2 id="重置应用" tabindex="-1">重置应用 <a class="header-anchor" href="#重置应用" aria-label="Permalink to &quot;重置应用&quot;">​</a></h2><p>要重置设置并清除本地数据：</p><ol><li>退出 ClipboxAI。</li><li>移除容器（这会删除历史记录与设置）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>重新打开应用并重新配置。如需移除 Keychain 中的 API key，必须单独在 <strong>Keychain Access</strong> 中删除。</li></ol><h2 id="如何收集调试日志" tabindex="-1">如何收集调试日志 <a class="header-anchor" href="#如何收集调试日志" aria-label="Permalink to &quot;如何收集调试日志&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 复制日志到桌面以便分享</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/ClipboxAI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>然后在 <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub</a> 上提交 issue 并附上这些日志。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>提交 issue 时，请包含：</p><ul><li>macOS 版本（苹果菜单 → 关于本机）</li><li>ClipboxAI 版本（应用菜单 → 关于）</li><li>复现步骤</li><li>日志（见上文）</li></ul><p>这有助于维护者更快定位并修复问题。</p>`,28)])])}const b=a(t,[["render",o]]);export{k as __pageData,b as default};
